"""Pure comparison checks against reports generated by the scene evaluator."""
import copy
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "scripts"))

from semantic_scene_cases import evaluate  # noqa: E402
from semantic_scene_comparison import compare_evaluations  # noqa: E402


LANGUAGES = ("en", "zh", "zh-en")
COHORTS = {
    "literal": ["scene-one"],
    "vague": ["scene-two"],
    "contrast": ["scene-three"],
}


def dataset(*, altered=False, candidates=4):
    return {
        "schema": "photohouse.semantic_scene_cases.v1",
        "review": {"natural_scenes": True, "labels_reviewed": True},
        "images": [
            {"id": f"img-{index}", "path": f"/photos/{index}.jpg",
             "sha256": f"{index:064x}"}
            for index in range(1, candidates + 1)
        ],
        "cases": [
            {"id": case_id, "relevant_images": [f"img-{index}"],
             "queries": {language: f"query {case_id} {language}{' changed' if altered else ''}"
                         for language in LANGUAGES}}
            for index, case_id in enumerate(("scene-one", "scene-two", "scene-three"), 1)
        ],
    }


def vectors(value, *, after=False):
    images = {}
    for index, item in enumerate(value["images"]):
        vector = [0.0] * 512
        vector[index] = 1.0
        images[item["id"]] = vector
    texts = {}
    for case in value["cases"]:
        relevant = case["relevant_images"][0]
        for language in LANGUAGES:
            texts[f'{case["id"]}:{language}'] = list(images[relevant])
    if after:
        # One query improves to rank 1; another falls behind all distractors.
        texts["scene-one:zh"] = list(images["img-1"])
        texts["scene-three:zh"] = list(images["img-4"])
    else:
        # Pessimistic score ties put scene one's zh behind all distractors.
        texts["scene-one:zh"] = list(images["img-2"])
    return images, texts


def reports():
    original, derived = dataset(), dataset(altered=True)
    before = evaluate(original, *vectors(original))
    after = evaluate(derived, *vectors(derived, after=True))
    return before, after


def test_comparison_separates_language_and_frozen_cohorts_with_rank_changes():
    before, after = reports()
    result = compare_evaluations(before, after, COHORTS)

    assert result["schema"] == "photohouse.semantic_scene_comparison.v1"
    assert result["before_dataset_sha256"] == before["dataset_sha256"]
    assert result["after_dataset_sha256"] == after["dataset_sha256"]
    assert result["before_dataset_sha256"] != result["after_dataset_sha256"]
    assert result["candidate_count"] == 4 and result["matched_case_count"] == 3
    assert result["cohort_labels"] == ["contrast", "literal", "vague"]
    assert result["overall"]["cases"] == 3
    assert result["overall"]["queries"] == 9
    assert result["overall"]["rank_gains"] == 1
    assert result["overall"]["rank_regressions"] == 1
    assert result["overall"]["rank_ties"] == 7
    assert result["overall"]["top1_improved"] == 1
    assert result["overall"]["top1_lost"] == 1
    assert result["overall"]["regression_case_ids"] == ["scene-three"]
    assert result["languages"]["zh"]["rank_gains"] == 1
    assert result["languages"]["zh"]["rank_regressions"] == 1
    assert result["languages"]["en"]["rank_ties"] == 3
    assert result["cohorts"]["literal"]["overall"]["rank_gains"] == 1
    assert result["cohorts"]["literal"]["languages"]["zh"]["top1_improved"] == 1
    assert result["cohorts"]["contrast"]["overall"]["regression_case_ids"] == ["scene-three"]
    assert result["cohorts"]["vague"]["overall"]["rank_ties"] == 3
    assert result["activation_approved"] is False
    assert result["semantic_faithfulness_qualified"] is False
    assert "recall_at_5" not in repr(result)


@pytest.mark.parametrize("mutate", [
    lambda report: report.update(extra="private query"),
    lambda report: report.update(schema="wrong"),
    lambda report: report.update(dataset_sha256="private query"),
    lambda report: report.update(candidate_count=True),
    lambda report: report.update(top_k=4),
    lambda report: report.update(activation_approved=True),
    lambda report: report.update(family_relevance_measured=True),
    lambda report: report.update(dialect_relevance_measured=True),
    lambda report: report.update(review_declarations={"natural_scenes": True}),
    lambda report: report.update(overall={**report["overall"], "top1": -1}),
    lambda report: report.update(overall={**report["overall"], "mean_reciprocal_rank": 0.0}),
    lambda report: report.update(overall={**report["overall"], "recall_at_5": float("nan")}),
    lambda report: report.update(overall={**report["overall"], "recall_at_5": 2.0}),
    lambda report: report["cases"][0]["ranks"].update(zh=999),
    lambda report: report["cases"][0].update(worst_language_rank=2),
    lambda report: report["cases"][0].update(all_languages_top1=True),
    lambda report: report["cases"][1].update(case_id=report["cases"][0]["case_id"]),
])
def test_invalid_report_contract_or_inconsistent_aggregates_use_fixed_error(mutate):
    before, after = reports()
    mutate(before)
    with pytest.raises(ValueError, match="^invalid_semantic_scene_comparison$") as caught:
        compare_evaluations(before, after, COHORTS)
    assert "private query" not in str(caught.value)


@pytest.mark.parametrize("cohorts", [
    {"literal": ["scene-one"], "vague": ["scene-two"]},
    {"literal": ["scene-one", "scene-two"], "vague": ["scene-two", "scene-three"]},
    {"literal": ["scene-one", "scene-two", "scene-three"], "empty": []},
    {"Unsafe query text": ["scene-one"], "vague": ["scene-two"], "contrast": ["scene-three"]},
    {f"group{index}": [case_id] for index, case_id in enumerate(
        ("scene-one", "scene-two", "scene-three", "scene-four", "scene-five",
         "scene-six", "scene-seven", "scene-eight", "scene-nine"))},
])
def test_cohorts_must_be_safe_bounded_and_partition_case_ids(cohorts):
    before, after = reports()
    with pytest.raises(ValueError, match="^invalid_semantic_scene_comparison$"):
        compare_evaluations(before, after, cohorts)


@pytest.mark.parametrize("mutation", ["case_set", "candidate_count", "review_declarations"])
def test_two_reports_must_share_case_candidate_and_review_contract(mutation):
    before, after = reports()
    after = copy.deepcopy(after)
    if mutation == "case_set":
        after["cases"].pop()
        after["matched_case_count"] -= 1
        after["all_languages_top1_cases"] = sum(
            case["all_languages_top1"] for case in after["cases"])
        # The internally valid smaller report no longer matches the original set.
        after["languages"] = {
            language: {
                "queries": 2, "top1": 2, "top5": 2,
                "mean_reciprocal_rank": 1.0, "recall_at_5": 1.0,
            } for language in LANGUAGES
        }
        after["overall"] = {
            "queries": 6, "top1": 6, "top5": 6,
            "mean_reciprocal_rank": 1.0, "recall_at_5": 1.0,
        }
    elif mutation == "candidate_count":
        after["candidate_count"] = 8
        after["effective_top_k"] = 5
    else:
        after["review_declarations"]["labels_reviewed"] = False
    with pytest.raises(ValueError, match="^invalid_semantic_scene_comparison$"):
        compare_evaluations(before, after, COHORTS)


def test_top_five_losses_and_gains_are_visible_even_when_aggregate_is_unchanged():
    original, derived = dataset(candidates=8), dataset(altered=True, candidates=8)
    before = evaluate(original, *vectors(original))
    after = evaluate(derived, *vectors(derived, after=True))
    assert before["cases"][0]["ranks"]["zh"] == 8
    assert after["cases"][2]["ranks"]["zh"] == 8
    result = compare_evaluations(before, after, COHORTS)
    assert result["overall"]["top5_before"] == result["overall"]["top5_after"] == 8
    literal = result["cohorts"]["literal"]["languages"]["zh"]
    contrast = result["cohorts"]["contrast"]["languages"]["zh"]
    assert (literal["top5_before"], literal["top5_after"]) == (0, 1)
    assert (contrast["top5_before"], contrast["top5_after"]) == (1, 0)
    assert literal["mean_reciprocal_rank_before"] == 0.125
    assert literal["mean_reciprocal_rank_after"] == 1.0
    assert contrast["mean_reciprocal_rank_after"] == 0.125
